import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.client.event.RegisterGuiOverlaysEvent;
import net.minecraftforge.client.gui.overlay.IGuiOverlay;
import net.minecraftforge.client.gui.overlay.VanillaGuiOverlay;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;

@Mod.EventBusSubscriber(modid="irons_spellbooks", value={Dist.CLIENT}, bus=Mod.EventBusSubscriber.Bus.MOD)
public class OverlayRegistry {
    @SubscribeEvent
    public static void onRegisterOverlays(RegisterGuiOverlaysEvent event) {
        event.registerBelow(VanillaGuiOverlay.CROSSHAIR.id(), "cast_bar", (IGuiOverlay)CastBarOverlay.instance);
        event.registerAbove(VanillaGuiOverlay.AIR_LEVEL.id(), "mana_overlay", (IGuiOverlay)ManaBarOverlay.instance);
        event.registerAbove(VanillaGuiOverlay.EXPERIENCE_BAR.id(), "spell_bar", (IGuiOverlay)SpellBarOverlay.instance);
        event.registerAbove(VanillaGuiOverlay.EXPERIENCE_BAR.id(), "recast_bar", (IGuiOverlay)RecastOverlay.instance);
        event.registerAboveAll("spell_wheel", (IGuiOverlay)SpellWheelOverlay.instance);
        event.registerAboveAll("screen_effects", (IGuiOverlay)ScreenEffectsOverlay.instance);
        event.registerAboveAll("screen_tooltip", (IGuiOverlay)ScreenTooltipOverlay.instance);
    }
}

